	m.read_from_versioned(mut r, version, flexible)!
	r.complete()!
}

fn (mut m AddPartitionsToTxnResponse) read_from_versioned(mut r kbin.Reader, version i16, flexible bool) ! {
	_ = version
	_ = flexible
	mut arr_len := 0
	_ = arr_len
	m.throttle_millis = r.read_int32()
	if version >= 4 {
		m.error_code = r.read_int16()
	}
	if version >= 4 {
		if flexible {
			arr_len = r.read_compact_array_len()
		} else {
			arr_len = r.read_array_len()
		}
		mut arr_transactions := []AddPartitionsToTxnResponseTransaction{cap: if arr_len > 0 {
			arr_len
		} else {
			0
		}}
		for _ in 0 .. arr_len {
			mut item_transactions := AddPartitionsToTxnResponseTransaction{}
			item_transactions.read_from_versioned(mut r, version, flexible)!
			arr_transactions << item_transactions
		}
		m.transactions = arr_transactions
	}
	if version <= 3 {
		if flexible {
			arr_len = r.read_compact_array_len()
		} else {
			arr_len = r.read_array_len()
		}
		mut arr_topics := []AddPartitionsToTxnResponseTopic{cap: if arr_len > 0 {
			arr_len
		} else {
			0
		}}
		for _ in 0 .. arr_len {
			mut item_topics := AddPartitionsToTxnResponseTopic{}
			item_topics.read_from_versioned(mut r, version, flexible)!
			arr_topics << item_topics
		}
		m.topics = arr_topics
	}
	if flexible {
		num_tags := r.read_uvarint()
		for _ in 0 .. num_tags {
			tag := r.read_uvarint()
			size := int(r.read_uvarint())
			data := r.span(size)
			if r.ok() {
				m.unknown_tags << UnknownTag{
					tag:  tag
					data: data.clone()
				}
			}
		}
	}
	r.complete()!
}
